//! Shared by the integration tests. Lives in `common/mod.rs`, not `common.rs`, so
//! cargo does not build it as a test file of its own.

use std::path::Path;
use std::process::Command;
use std::sync::OnceLock;

/// Relative to the crate root, which is where `cargo test` runs integration tests.
const TEST_VIDEO: &str = "data/test.mp4";
const GENERATOR: &str = "script/gen_test_data.sh";

/// The test video's path, generated by `script/gen_test_data.sh` the first time a
/// test asks for it. If it cannot be generated the test fails with the script's
/// output: a missing video must never turn into a silently skipped test.
pub fn test_video() -> &'static str {
    // Tests in one file run in parallel; only the first one generates the video.
    static READY: OnceLock<()> = OnceLock::new();
    READY.get_or_init(|| {
        if Path::new(TEST_VIDEO).exists() {
            return;
        }
        let output = Command::new("sh")
            .arg(GENERATOR)
            .output()
            .unwrap_or_else(|e| panic!("could not run {GENERATOR}: {e}"));
        assert!(
            output.status.success() && Path::new(TEST_VIDEO).exists(),
            "{GENERATOR} could not generate {TEST_VIDEO}:\n{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr),
        );
    });
    TEST_VIDEO
}
